import {
    ArrayShape,
    type CallExpressionShape,
    type Diagnostics,
    type Factory,
    type Record,
    type Shape,
    StringShape,
} from '@servicenow/sdk-build-core'
import { generateDeprecatedDiagnostics } from '../utils'
import { BCP47_LANGUAGE_TAG_PATTERN, generatePlural } from '../column-plugin'

/**
 * Extracts the label for the default language from a label shape.
 * When label is a string, returns it directly.
 * When label is an array of documentation objects, finds the entry matching
 * the default language and returns its label property.
 */
export function getLabelForDefaultLanguage(labelShape: Shape, tableDefaultLanguage: string): Shape | undefined {
    if (labelShape.isString()) {
        return labelShape.asString()
    }
    if (labelShape.isArray()) {
        const docs = labelShape.asArray().getElements()
        for (const doc of docs) {
            const docObj = doc.asObject()
            const lang = docObj.get('language').ifString()?.getValue()
            if (lang === tableDefaultLanguage || (!lang && tableDefaultLanguage === 'en')) {
                return docObj.get('label').ifString()
            }
        }
        if (docs.length > 0) {
            return docs[0]?.asObject().get('label').ifString()
        }
    }
    return undefined
}

export async function getDocumentationRecords(
    callExpression: CallExpressionShape,
    aliasedKeys: globalThis.Record<string, string[]>,
    factory: Factory,
    diagnostics: Diagnostics,
    generateDefaultDoc: boolean = false,
    tableDefaultLanguage: string = 'en'
) {
    const column = callExpression.getArgument(0).asObject()
    const documentation = column.get('label')
    const columnName = column.get('name')
    if (!documentation.if([ArrayShape, StringShape])) {
        return [
            await factory.createRecord({
                source: callExpression,
                table: 'sys_documentation',
                properties: column.transform(({ $ }) => ({
                    name: $.from('table'),
                    element: $.val(columnName),
                    language: $.def(tableDefaultLanguage),
                    hint: $.def(''),
                    label: $.val(documentation.ifDefined() ?? columnName),
                    plural: $.val(
                        generatePlural(
                            documentation.ifDefined()?.asString().getValue() ?? columnName.asString().getValue()
                        )
                    ),
                })),
            }),
        ]
    }

    if (documentation.ifArray()) {
        const docRecords: Record[] = []
        const languages = new Set<string>()
        for (const doc of documentation.asArray().getElements()) {
            const docObject = doc.asObject().withAliasedKeys(aliasedKeys)
            generateDeprecatedDiagnostics(docObject, diagnostics)
            const language = docObject.get('language').ifString()?.getValue()
            if (language) {
                if (!BCP47_LANGUAGE_TAG_PATTERN.test(language)) {
                    diagnostics.error(
                        doc.getOriginalNode(),
                        `'language' must be a valid BCP 47 language tag (e.g., 'en', 'es', 'en-US', 'zh-Hans')`
                    )
                }
                if (languages.has(language)) {
                    diagnostics.error(
                        doc.getOriginalNode(),
                        `Duplicate language '${language}' found. Each language must be unique per column.`
                    )
                }
                languages.add(language)
            }
            docRecords.push(
                await factory.createRecord({
                    source: callExpression,
                    table: 'sys_documentation',
                    properties: docObject.transform(({ $ }) => ({
                        name: $.val(column.get('table')),
                        element: $.val(column.get('name')),
                        language: $.def(tableDefaultLanguage),
                        hint: $.def(''),
                        help: $,
                        label: $,
                        plural: $,
                        url: $,
                        url_target: $.from('urlTarget'),
                    })),
                })
            )
        }

        return docRecords
    }

    if (!generateDefaultDoc) {
        return []
    }

    return [
        await factory.createRecord({
            source: callExpression,
            table: 'sys_documentation',
            properties: column.transform(({ $ }) => ({
                name: $.from('table'),
                element: $.val(columnName),
                language: $.def(tableDefaultLanguage),
                hint: $.def(''),
                label: $.val(documentation.ifDefined() ?? columnName),
                plural: $.val(
                    generatePlural(documentation.ifDefined()?.asString().getValue() ?? columnName.asString().getValue())
                ),
            })),
        }),
    ]
}

export async function getChoiceRecords(
    callExpression: CallExpressionShape,
    aliasedKeys: globalThis.Record<string, string[]>,
    factory: Factory,
    diagnostics: Diagnostics,
    tableDefaultLanguage: string = 'en'
) {
    const column = callExpression.getArgument(0).asObject()
    const choiceArg = column.has('choices') ? column.get('choices').asObject().withAliasedKeys(aliasedKeys) : undefined
    if (!choiceArg) {
        return []
    }

    const records: Record[] = []
    for (const [idx, [choiceValue, choice]] of Object.entries(choiceArg.properties()).entries()) {
        if (choice.isObject()) {
            generateDeprecatedDiagnostics(choice.withAliasedKeys(aliasedKeys), diagnostics)
        }
        records.push(
            await factory.createRecord({
                source: callExpression,
                table: 'sys_choice',
                properties: choice.isString()
                    ? {
                          name: column.get('table').asString().getValue(),
                          element: column.get('name').asString().getValue(),
                          label: choice,
                          value: choiceValue,
                          sequence: idx + 1,
                          language: tableDefaultLanguage,
                      }
                    : choice.asObject().transform(({ $ }) => ({
                          name: $.val(column.get('table')),
                          element: $.val(column.get('name')),
                          label: $,
                          value: $.val(choiceValue),
                          sequence: $,
                          dependent_value: $.from('dependentValue'),
                          hint: $,
                          inactive: $.toBoolean().def(false),
                          inactive_on_update: $.from('inactiveOnUpdate').toBoolean().def(false),
                          language: $.def(tableDefaultLanguage),
                      })),
            })
        )
    }

    return records
}
